--
-- Name: accounting_apply_balance_for_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_apply_balance_for_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  journal_period_id uuid;
BEGIN
  SELECT period_id INTO journal_period_id
  FROM journal_entry
  WHERE organization_id = NEW.organization_id AND id = NEW.journal_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACCOUNTING_JOURNAL_NOT_FOUND';
  END IF;

  INSERT INTO account_balance (
    organization_id, period_id, ledger_account_id, debit_total, credit_total, balance
  )
  VALUES (
    NEW.organization_id, journal_period_id, NEW.ledger_account_id,
    NEW.debit, NEW.credit, NEW.debit - NEW.credit
  )
  ON CONFLICT (organization_id, period_id, ledger_account_id)
  DO UPDATE SET debit_total = account_balance.debit_total + EXCLUDED.debit_total,
                credit_total = account_balance.credit_total + EXCLUDED.credit_total,
                balance = account_balance.balance + EXCLUDED.balance;

  RETURN NEW;
END;
$$;


--
-- Name: accounting_assert_journal_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_assert_journal_balanced() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  journal_id uuid;
  debit_total numeric(20, 2);
  credit_total numeric(20, 2);
  line_count integer;
BEGIN
  IF TG_TABLE_NAME = 'journal_entry' THEN
    journal_id := NEW.id;
  ELSE
    journal_id := NEW.journal_entry_id;
  END IF;

  SELECT count(*)::integer, COALESCE(sum(debit), 0), COALESCE(sum(credit), 0)
  INTO line_count, debit_total, credit_total
  FROM journal_line
  WHERE organization_id = NEW.organization_id AND journal_entry_id = journal_id;

  IF line_count = 0 OR debit_total <> credit_total THEN
    RAISE EXCEPTION 'ACCOUNTING_JOURNAL_UNBALANCED';
  END IF;

  RETURN NULL;
END;
$$;


--
-- Name: accounting_lock_posting_period(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accounting_lock_posting_period() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  period_row accounting_period%ROWTYPE;
BEGIN
  SELECT * INTO period_row
  FROM accounting_period
  WHERE organization_id = NEW.organization_id AND id = NEW.period_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ACCOUNTING_PERIOD_NOT_FOUND';
  END IF;

  IF NEW.entry_date < period_row.period_start OR NEW.entry_date > period_row.period_end THEN
    RAISE EXCEPTION 'ACCOUNTING_ENTRY_DATE_OUTSIDE_PERIOD';
  END IF;

  IF period_row.status NOT IN ('open', 'reopened') THEN
    RAISE EXCEPTION 'ACCOUNTING_PERIOD_CLOSED';
  END IF;

  RETURN NEW;
END;
$$;


