--
-- Name: apply_tenant_rls(regclass); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_tenant_rls(target regclass) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  policy_name text := format('%s_tenant_isolation', target::text);
BEGIN
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', target);
  EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', target);
  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', policy_name, target);
  EXECUTE format(
    'CREATE POLICY %I ON %s
       USING (organization_id = current_organization_id())
       WITH CHECK (organization_id = current_organization_id())',
    policy_name, target
  );
  -- WITH CHECK is what prevents INSERT or UPDATE into another tenant. USING
  -- alone would let a write land in the wrong organization and simply become
  -- invisible afterwards, which is worse than a loud failure.
END
$$;


--
-- Name: biometric_punch_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.biometric_punch_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.id, NEW.organization_id, NEW.device_id, NEW.pin, NEW.device_local_time,
      NEW.occurred_at, NEW.corrected_at, NEW.applied_offset_seconds, NEW.received_at,
      NEW.status_code, NEW.verify_mode, NEW.reader_key, NEW.external_event_id, NEW.raw_line,
      NEW.direction_at_receipt, NEW.meaning, NEW.dry_run_at_receipt)
     IS DISTINCT FROM
     (OLD.id, OLD.organization_id, OLD.device_id, OLD.pin, OLD.device_local_time,
      OLD.occurred_at, OLD.corrected_at, OLD.applied_offset_seconds, OLD.received_at,
      OLD.status_code, OLD.verify_mode, OLD.reader_key, OLD.external_event_id, OLD.raw_line,
      OLD.direction_at_receipt, OLD.meaning, OLD.dry_run_at_receipt) THEN
    RAISE EXCEPTION 'biometric_punch: the receipt and its reading are fixed at arrival (D37)'
      USING ERRCODE = 'check_violation';
  END IF;
  -- Once a punch became an event, or joined a burst, its person and those links
  -- stay: clearing a pointer first does not free the owner. Changing it is a
  -- review, not an update.
  IF OLD.attendance_event_id IS NOT NULL
     AND (NEW.attendance_event_id IS DISTINCT FROM OLD.attendance_event_id
          OR NEW.user_id IS DISTINCT FROM OLD.user_id
          OR NEW.pin_mapping_id IS DISTINCT FROM OLD.pin_mapping_id) THEN
    RAISE EXCEPTION 'biometric_punch: an applied punch keeps its event and its person'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.duplicate_of IS NOT NULL
     AND (NEW.duplicate_of IS NULL
          OR NEW.user_id IS DISTINCT FROM OLD.user_id
          OR NEW.pin_mapping_id IS DISTINCT FROM OLD.pin_mapping_id) THEN
    RAISE EXCEPTION 'biometric_punch: a duplicate stays in a burst of the same person'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: create_audit_partition(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_audit_partition(month_start date) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  partition_name text := format('audit_entry_%s', to_char(month_start, 'YYYY_MM'));
  month_end date := (month_start + interval '1 month')::date;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = partition_name) THEN
    EXECUTE format(
      'CREATE TABLE %I PARTITION OF audit_entry FOR VALUES FROM (%L) TO (%L)',
      partition_name, month_start, month_end
    );
    -- Grants do not inherit to new partitions; each needs them explicitly, and
    -- each needs UPDATE/DELETE revoked or the append-only guarantee has a hole.
    EXECUTE format('GRANT SELECT, INSERT ON %I TO tapcrm_app', partition_name);
    EXECUTE format('REVOKE UPDATE, DELETE ON %I FROM tapcrm_app', partition_name);
    -- RLS does NOT inherit for direct partition access. PostgreSQL applies the
    -- parent's policy only when the query goes through the parent; naming a
    -- partition directly uses that partition's own policies. Since the app role
    -- is granted SELECT on each partition, an omitted policy here would be a
    -- real tenant-isolation hole.
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', partition_name);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', partition_name);
    EXECUTE format(
      'CREATE POLICY %I ON %I
         USING (organization_id = current_organization_id())
         WITH CHECK (organization_id = current_organization_id())',
      partition_name || '_tenant_isolation', partition_name
    );
  END IF;
END
$$;


