--
-- Name: resolve_webhook_actor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_webhook_actor(p_organization_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT u.id
    FROM public.app_user AS u
   WHERE u.organization_id = p_organization_id
     AND u.status          = 'active'
     AND u.account_type   IN ('super-admin', 'company_admin', 'admin')
   ORDER BY CASE u.account_type
              WHEN 'super-admin'   THEN 0
              WHEN 'company_admin' THEN 1
              WHEN 'admin'         THEN 2
              ELSE 3
            END,
            u.created_at
   LIMIT 1
$$;


