--
-- Name: social_account_scope_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_account_scope_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  connection_client uuid;
BEGIN
  SELECT c.client_id INTO connection_client
  FROM social_connection c
  WHERE c.organization_id = NEW.organization_id AND c.id = NEW.connection_id;
  -- A missing connection is reported by social_account_connection_fkey.
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;
  IF connection_client IS NOT NULL
     AND (connection_client <> NEW.client_id OR NEW.location_id IS NOT NULL) THEN
    RAISE EXCEPTION 'social_account: a client connection serves only its own client'
      USING ERRCODE = 'check_violation';
  END IF;
  IF connection_client IS NULL AND NEW.location_id IS NULL THEN
    RAISE EXCEPTION 'social_account: a company connection serves a client through one of its locations'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: social_connection_location_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_connection_location_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM social_connection c
    WHERE c.organization_id = NEW.organization_id
      AND c.id = NEW.connection_id
      AND c.client_id IS NULL
  ) THEN
    RAISE EXCEPTION 'social_connection_location: locations belong to a company-wide connection'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: social_connection_origin_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.social_connection_origin_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.connected_via IS DISTINCT FROM OLD.connected_via THEN
    RAISE EXCEPTION 'social_connection: a connection keeps the origin it was created with'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.connected_via = 'client_portal' AND NOT EXISTS (
    SELECT 1 FROM app_user u
    WHERE u.organization_id = NEW.organization_id
      AND u.id = NEW.created_by
      AND u.account_type = 'client'
      AND u.client_id = NEW.client_id
  ) THEN
    RAISE EXCEPTION 'social_connection: a client-portal connection is made by a login of that client'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;


