--
-- Name: sync_biometric_device_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_biometric_device_directory() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    OLD.serial_number IS DISTINCT FROM NEW.serial_number OR
    OLD.organization_id IS DISTINCT FROM NEW.organization_id
  ) THEN
    DELETE FROM biometric_device_directory
    WHERE organization_id = OLD.organization_id AND device_id = OLD.id;
  END IF;

  IF EXISTS (
    SELECT 1 FROM biometric_device_directory
    WHERE serial_number = NEW.serial_number
      AND NOT (organization_id = NEW.organization_id AND device_id = NEW.id)
  ) THEN
    RAISE EXCEPTION 'Device serial % is registered to another company', NEW.serial_number
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO biometric_device_directory (serial_number, organization_id, device_id)
  VALUES (NEW.serial_number, NEW.organization_id, NEW.id)
  ON CONFLICT (serial_number) DO NOTHING;
  RETURN NEW;
END
$$;


--
-- Name: sync_identity_email_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_identity_email_directory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM identity_email_directory
    WHERE organization_id = OLD.organization_id AND user_id = OLD.id;
    RETURN OLD;
  END IF;

  IF TG_OP = 'UPDATE' AND (
    OLD.email IS DISTINCT FROM NEW.email OR
    OLD.organization_id IS DISTINCT FROM NEW.organization_id
  ) THEN
    DELETE FROM identity_email_directory
    WHERE organization_id = OLD.organization_id AND user_id = OLD.id;
  END IF;

  IF NEW.email IS NOT NULL THEN
    IF EXISTS (
      SELECT 1
      FROM identity_email_directory
      WHERE email = NEW.email
        AND NOT (user_id = NEW.id AND organization_id = NEW.organization_id)
    ) THEN
      RAISE EXCEPTION 'Email is already assigned to another identity'
        USING ERRCODE = '23505';
    END IF;

    INSERT INTO identity_email_directory(email, user_id, organization_id)
    VALUES (NEW.email, NEW.id, NEW.organization_id)
    ON CONFLICT (email) DO UPDATE
      SET updated_at = now();
  END IF;

  RETURN NEW;
END
$$;


