    user_id uuid NOT NULL,
    work_date date NOT NULL,
    window_start timestamp with time zone NOT NULL,
    window_end timestamp with time zone NOT NULL,
    state text DEFAULT 'open'::text NOT NULL,
    close_due_at timestamp with time zone NOT NULL,
    shift_snapshot jsonb NOT NULL,
    shift_source text NOT NULL,
    placement_snapshot jsonb NOT NULL,
    day_type text NOT NULL,
    status text,
    present_units smallint DEFAULT 0 NOT NULL,
    paid_leave_units smallint DEFAULT 0 NOT NULL,
    unpaid_leave_units smallint DEFAULT 0 NOT NULL,
    absent_units smallint DEFAULT 0 NOT NULL,
    holiday_units smallint DEFAULT 0 NOT NULL,
    worked_minutes integer DEFAULT 0 NOT NULL,
    break_minutes integer DEFAULT 0 NOT NULL,
    late_minutes integer DEFAULT 0 NOT NULL,
    early_exit_minutes integer DEFAULT 0 NOT NULL,
    overtime_minutes integer DEFAULT 0 NOT NULL,
    night_minutes integer DEFAULT 0 NOT NULL,
    arrival_at timestamp with time zone,
    departure_at timestamp with time zone,
    is_wfh boolean DEFAULT false NOT NULL,
    flags text[] DEFAULT '{}'::text[] NOT NULL,
    attribution_flags text[] DEFAULT '{}'::text[] NOT NULL,
    provenance jsonb DEFAULT '{}'::jsonb NOT NULL,
    input_version integer DEFAULT 1 NOT NULL,
    calculated_input_version integer DEFAULT 0 NOT NULL,
    calculation_version integer DEFAULT 0 NOT NULL,
    breaks_evaluated_version integer,
    rules_version text DEFAULT 'uncalculated'::text NOT NULL,
    calculated_at timestamp with time zone,
    closed_at timestamp with time zone,
    closed_by text,
    input_changed_at timestamp with time zone DEFAULT now() NOT NULL,
    breaks_evaluation_revision bigint DEFAULT 0 NOT NULL,
    break_policy_snapshot jsonb,
    CONSTRAINT attendance_record_check CHECK ((window_end > window_start)),
    CONSTRAINT attendance_record_check1 CHECK ((((((present_units + paid_leave_units) + unpaid_leave_units) + absent_units) + holiday_units) =
CASE
    WHEN ((status IS NULL) OR (status = ANY (ARRAY['not-evaluated'::text, 'not-employed'::text]))) THEN 0
    ELSE 2
END)),
    CONSTRAINT attendance_record_closed_by_check CHECK ((closed_by = ANY (ARRAY['punch-out'::text, 'auto-close'::text, 'no-show'::text, 'correction'::text]))),
    CONSTRAINT attendance_record_day_type_check CHECK ((day_type = ANY (ARRAY['working'::text, 'week-off'::text, 'holiday'::text, 'not-employed'::text]))),
    CONSTRAINT attendance_record_state_check CHECK ((state = ANY (ARRAY['open'::text, 'closed'::text]))),
    CONSTRAINT attendance_record_status_check CHECK ((status = ANY (ARRAY['present'::text, 'half-day'::text, 'absent'::text, 'leave'::text, 'half-day-leave'::text, 'holiday'::text, 'not-evaluated'::text, 'not-employed'::text])))
);

ALTER TABLE ONLY public.attendance_record FORCE ROW LEVEL SECURITY;


--
-- Name: attendance_refresh_request; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attendance_refresh_request (
    id uuid DEFAULT uuidv7() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    source_event_id uuid NOT NULL,
    from_date date NOT NULL,
    to_date date,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    failed_at timestamp with time zone,
    replays integer DEFAULT 0 NOT NULL,
    CONSTRAINT attendance_refresh_request_check CHECK (((to_date IS NULL) OR (to_date >= from_date))),
    CONSTRAINT attendance_refresh_request_check1 CHECK (((completed_at IS NULL) OR (failed_at IS NULL)))
);

ALTER TABLE ONLY public.attendance_refresh_request FORCE ROW LEVEL SECURITY;


--
-- Name: attendance_review_item; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attendance_review_item (
    id uuid DEFAULT uuidv7() NOT NULL,
    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    work_date date NOT NULL,
    kind text NOT NULL,
    event_id uuid,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    opened_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    resolution_source text,
    resolution_note text,
    correction_id uuid,
    CONSTRAINT attendance_review_item_check CHECK (((resolved_at IS NULL) OR (resolution_source IS NOT NULL))),
    CONSTRAINT attendance_review_item_check1 CHECK ((((resolved_at IS NULL) AND (resolution_source IS NULL) AND (resolved_by IS NULL) AND (correction_id IS NULL)) OR ((resolved_at IS NOT NULL) AND (resolution_source = 'system'::text) AND (resolved_by IS NULL)) OR ((resolved_at IS NOT NULL) AND (resolution_source = 'human'::text) AND (resolved_by IS NOT NULL)))),
    CONSTRAINT attendance_review_item_kind_check CHECK ((kind = ANY (ARRAY['assumed-departure'::text, 'auto-close-failed'::text, 'reconciled-from-auto-close'::text, 'overtime-on-assumed'::text, 'same-instant-conflict'::text, 'departure-without-arrival'::text, 'previous-session-unconfirmed'::text, 'worked-remotely-without-approval'::text, 'punched-on-leave'::text, 'holiday-worked'::text, 'activity-after-finish'::text, 'late-synced-punch'::text, 'outside-shift-window'::text, 'overlapping-shift-windows'::text, 'not-evaluated'::text, 'retime-changes-subject'::text]))),
    CONSTRAINT attendance_review_item_resolution_source_check CHECK ((resolution_source = ANY (ARRAY['human'::text, 'system'::text])))
);

ALTER TABLE ONLY public.attendance_review_item FORCE ROW LEVEL SECURITY;


--
-- Name: attendance_setting; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.attendance_setting (
    id uuid DEFAULT uuidv7() NOT NULL,
    organization_id uuid NOT NULL,
    effective_from date NOT NULL,
    arrival_policy text DEFAULT 'device-or-web'::text NOT NULL,
    client_time_tolerance_minutes integer DEFAULT 15 NOT NULL,
    night_window_from time without time zone,
    night_window_to time without time zone,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT attendance_setting_arrival_policy_check CHECK ((arrival_policy = ANY (ARRAY['device-or-web'::text, 'device'::text]))),
    CONSTRAINT attendance_setting_check CHECK (((night_window_from IS NULL) = (night_window_to IS NULL))),
    CONSTRAINT attendance_setting_check1 CHECK (((night_window_from IS NULL) OR (night_window_from <> night_window_to))),
    CONSTRAINT attendance_setting_client_time_tolerance_minutes_check CHECK (((client_time_tolerance_minutes >= 0) AND (client_time_tolerance_minutes <= 1440)))
);

ALTER TABLE ONLY public.attendance_setting FORCE ROW LEVEL SECURITY;


--
-- Name: audit_archive; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_archive (
    id uuid DEFAULT uuidv7() NOT NULL,
    organization_id uuid NOT NULL,
    stream text NOT NULL,
    sequence_start bigint NOT NULL,
    sequence_end bigint NOT NULL,
    occurred_start timestamp with time zone NOT NULL,
    occurred_end timestamp with time zone NOT NULL,
    record_count integer NOT NULL,
    first_hash bytea NOT NULL,
    last_hash bytea NOT NULL,
    object_key text NOT NULL,
    object_checksum text NOT NULL,
    object_size_bytes bigint NOT NULL,
    encryption_key_id text NOT NULL,
    archived_at timestamp with time zone DEFAULT now() NOT NULL,
    storage_verified_at timestamp with time zone NOT NULL,
    status text DEFAULT 'archived'::text NOT NULL,
    purged_at timestamp with time zone,
    first_prev_hash bytea,
    CONSTRAINT audit_archive_object_size_bytes_check CHECK ((object_size_bytes >= 0)),
    CONSTRAINT audit_archive_range CHECK (((sequence_end >= sequence_start) AND (occurred_end >= occurred_start))),
    CONSTRAINT audit_archive_record_count_check CHECK ((record_count > 0)),
    CONSTRAINT audit_archive_status_check CHECK ((status = ANY (ARRAY['archived'::text, 'purged'::text]))),
    CONSTRAINT audit_archive_status_shape CHECK ((((status = 'archived'::text) AND (purged_at IS NULL)) OR ((status = 'purged'::text) AND (purged_at IS NOT NULL)))),
    CONSTRAINT audit_archive_stream_check CHECK ((stream = ANY (ARRAY['access'::text, 'activity'::text])))
);

ALTER TABLE ONLY public.audit_archive FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE audit_archive; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.audit_archive IS 'AU-4/AU-9 immutable archive manifests. Payloads are encrypted objects in centralized WORM storage; metadata preserves chain boundaries and checksums.';


--
-- Name: audit_entry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.audit_entry (
    organization_id uuid NOT NULL,
    stream text NOT NULL,
    sequence bigint NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    actor_id uuid,
    actor_type text NOT NULL,
    action text NOT NULL,
    target_type text NOT NULL,
    target_id uuid,
    before_data jsonb,
    after_data jsonb,
    reason text,
    source_ip inet,
    request_id text,
    hash_version smallint DEFAULT 1 NOT NULL,
    prev_hash bytea,
    hash bytea NOT NULL,
    legal_hold boolean DEFAULT false NOT NULL,
    CONSTRAINT audit_entry_actor_type_check CHECK ((actor_type = ANY (ARRAY['super-admin'::text, 'employee'::text, 'client'::text, 'service'::text, 'system'::text]))),
    CONSTRAINT audit_entry_stream_check CHECK ((stream = ANY (ARRAY['access'::text, 'activity'::text])))
)
PARTITION BY RANGE (occurred_at);

ALTER TABLE ONLY public.audit_entry FORCE ROW LEVEL SECURITY;


--
-- Name: TABLE audit_entry; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.audit_entry IS 'AU-2: append-only. UPDATE and DELETE are revoked from the application role. AU-4: retention is 7 years; entries older than 12 months move to archival storage.';


