    organization_id uuid NOT NULL,
    user_id uuid NOT NULL,
    leave_type_id uuid NOT NULL,
    kind text NOT NULL,
    from_date date NOT NULL,
    to_date date NOT NULL,
    from_half text DEFAULT 'full'::text NOT NULL,
    to_half text DEFAULT 'full'::text NOT NULL,
    days_consumed numeric(5,1) DEFAULT 0 NOT NULL,
    reason text NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    requested_by uuid NOT NULL,
    acknowledged_by uuid,
    acknowledged_at timestamp with time zone,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_note text,
    revoked_by uuid,
    revoked_at timestamp with time zone,
    recurrence_type text,
    recurrence_end date,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT leave_request_check CHECK ((to_date >= from_date)),
    CONSTRAINT leave_request_check1 CHECK ((EXTRACT(year FROM from_date) = EXTRACT(year FROM to_date))),
    CONSTRAINT leave_request_check2 CHECK (((recurrence_type IS NULL) OR (kind = 'attendance-mode'::text))),
    CONSTRAINT leave_request_check3 CHECK (((recurrence_type IS NULL) = (recurrence_end IS NULL))),
    CONSTRAINT leave_request_check4 CHECK (((recurrence_end IS NULL) OR (recurrence_end >= to_date))),
    CONSTRAINT leave_request_check5 CHECK (((decided_by IS NULL) OR (decided_by <> requested_by))),
    CONSTRAINT leave_request_check6 CHECK (((acknowledged_by IS NULL) = (acknowledged_at IS NULL))),
    CONSTRAINT leave_request_check7 CHECK (((decided_by IS NULL) = (decided_at IS NULL))),
    CONSTRAINT leave_request_check8 CHECK (((revoked_by IS NULL) = (revoked_at IS NULL))),
    CONSTRAINT leave_request_days_consumed_check CHECK ((days_consumed >= (0)::numeric)),
    CONSTRAINT leave_request_from_half_check CHECK ((from_half = ANY (ARRAY['full'::text, 'first'::text, 'second'::text]))),
    CONSTRAINT leave_request_kind_check CHECK ((kind = ANY (ARRAY['absence'::text, 'attendance-mode'::text]))),
    CONSTRAINT leave_request_recurrence_type_check CHECK ((recurrence_type = 'daily'::text)),
    CONSTRAINT leave_request_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'acknowledged'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT leave_request_to_half_check CHECK ((to_half = ANY (ARRAY['full'::text, 'first'::text, 'second'::text])))
);

