    CONSTRAINT seo_rank_scan_check CHECK (((status = 'found'::text) = ("position" IS NOT NULL))),
    CONSTRAINT seo_rank_scan_city_check CHECK (((city IS NULL) OR ((length(city) >= 1) AND (length(city) <= 100)))),
    CONSTRAINT seo_rank_scan_country_check CHECK (((length(country) >= 1) AND (length(country) <= 100))),
    CONSTRAINT seo_rank_scan_depth_check CHECK (((depth >= 10) AND (depth <= 100))),
    CONSTRAINT seo_rank_scan_device_check CHECK ((device = ANY (ARRAY['desktop'::text, 'mobile'::text]))),
    CONSTRAINT seo_rank_scan_engine_check CHECK ((engine = ANY (ARRAY['google'::text, 'bing'::text, 'google_local'::text]))),
    CONSTRAINT seo_rank_scan_keyword_check CHECK (((length(keyword) >= 1) AND (length(keyword) <= 200))),
    CONSTRAINT seo_rank_scan_message_check CHECK (((message IS NULL) OR (length(message) <= 1000))),
    CONSTRAINT seo_rank_scan_pages_requested_check CHECK (((pages_requested >= 0) AND (pages_requested <= 20))),
    CONSTRAINT seo_rank_scan_position_check CHECK ((("position" IS NULL) OR (("position" >= 1) AND ("position" <= 1000)))),
    CONSTRAINT seo_rank_scan_ranking_title_check CHECK (((ranking_title IS NULL) OR (length(ranking_title) <= 500))),
    CONSTRAINT seo_rank_scan_ranking_url_check CHECK (((ranking_url IS NULL) OR (length(ranking_url) <= 2000))),
    CONSTRAINT seo_rank_scan_results_checked_check CHECK (((results_checked IS NULL) OR ((results_checked >= 0) AND (results_checked <= 1000)))),
    CONSTRAINT seo_rank_scan_search_location_check CHECK ((length(search_location) <= 300)),
    CONSTRAINT seo_rank_scan_status_check CHECK ((status = ANY (ARRAY['found'::text, 'not-found'::text, 'failed'::text])))
);

